<?php
namespace xdecaro\Component\Inventory\Administrator\Service;
defined('_JEXEC') or die;
use Joomla\CMS\Factory; use Joomla\CMS\Language\Text; use Joomla\Database\DatabaseInterface; use Joomla\Database\ParameterType;
final class MovementService { public function __construct(private readonly DatabaseInterface $database){} public function record(int $itemId,string $quantityDelta,string $reason,?string $note,int $userId):void{$reason=trim($reason);$note=$note!==null?trim($note):null;if($itemId<1)throw new \InvalidArgumentException(Text::_('COM_XDECAROINVENTORY_ERROR_ITEM_REQUIRED'));if($reason==='')throw new \InvalidArgumentException(Text::_('COM_XDECAROINVENTORY_ERROR_REASON_REQUIRED'));if(mb_strlen($reason)>100||($note!==null&&mb_strlen($note)>500))throw new \InvalidArgumentException(Text::_('COM_XDECAROINVENTORY_ERROR_MOVEMENT_TOO_LONG'));$deltaMilli=self::toMilli($quantityDelta);if($deltaMilli===0)throw new \InvalidArgumentException(Text::_('COM_XDECAROINVENTORY_ERROR_ZERO_DELTA'));$delta=self::fromMilli($deltaMilli);$created=Factory::getDate()->toSql();$this->database->transactionStart();try{$update=$this->database->createQuery()->update($this->database->quoteName('#__xdecaroinventory_items'))->set($this->database->quoteName('quantity').' = '.$this->database->quoteName('quantity').' + :delta_set')->set($this->database->quoteName('modified').' = :modified')->set($this->database->quoteName('modified_by').' = :modified_by')->where($this->database->quoteName('id').' = :item_id')->where($this->database->quoteName('quantity').' + :delta_guard >= 0')->bind(':delta_set',$delta,ParameterType::STRING)->bind(':modified',$created,ParameterType::STRING)->bind(':modified_by',$userId,ParameterType::INTEGER)->bind(':item_id',$itemId,ParameterType::INTEGER)->bind(':delta_guard',$delta,ParameterType::STRING);$this->database->setQuery($update)->execute();if($this->database->affectedRows()!==1){$exists=$this->database->createQuery()->select($this->database->quoteName('id'))->from($this->database->quoteName('#__xdecaroinventory_items'))->where($this->database->quoteName('id').' = :item_id')->bind(':item_id',$itemId,ParameterType::INTEGER);$this->database->setQuery($exists);if($this->database->loadResult()===null)throw new \DomainException(Text::_('COM_XDECAROINVENTORY_ERROR_ITEM_NOT_FOUND'));throw new \DomainException(Text::_('COM_XDECAROINVENTORY_ERROR_NEGATIVE_STOCK'));}$insert=$this->database->createQuery()->insert($this->database->quoteName('#__xdecaroinventory_movements'))->columns($this->database->quoteName(['item_id','quantity_delta','reason','note','created','created_by']))->values(':item_id, :quantity_delta, :reason, :note, :created, :created_by')->bind(':item_id',$itemId,ParameterType::INTEGER)->bind(':quantity_delta',$delta,ParameterType::STRING)->bind(':reason',$reason,ParameterType::STRING)->bind(':note',$note,ParameterType::STRING)->bind(':created',$created,ParameterType::STRING)->bind(':created_by',$userId,ParameterType::INTEGER);$this->database->setQuery($insert)->execute();$this->database->transactionCommit();}catch(\Throwable $e){$this->database->transactionRollback();throw $e;}} private static function toMilli(string $value):int{$value=trim(str_replace(',','.',$value));if(!preg_match('/^[+-]?\d{1,11}(?:\.\d{1,3})?$/',$value))throw new \InvalidArgumentException(Text::_('COM_XDECAROINVENTORY_ERROR_INVALID_QUANTITY'));$negative=str_starts_with($value,'-');$unsigned=ltrim($value,'+-');[$whole,$fraction]=array_pad(explode('.',$unsigned,2),2,'');$fraction=str_pad($fraction,3,'0');$milli=((int)$whole*1000)+(int)$fraction;return $negative?-$milli:$milli;} private static function fromMilli(int $value):string{$sign=$value<0?'-':'';$value=abs($value);return $sign.intdiv($value,1000).'.'.str_pad((string)($value%1000),3,'0',STR_PAD_LEFT);} }
